void THandlerTesterSide::PublishSettings()
{
    //AI(W906-GB-P6) 20260926: rulings C-2 (暫照建議，待使用者確認 decision #5): the engine reads these instead of its own ini.
    //   3A / Q1(a): the Auto Retest brand the Handler holds now (golden learning kept on both sides).
    //   4A / Q4 A : the Handler-ID reply format from the Handler's config.
    //   Called before every bridge start, after the Handler's own brand learning (HandlerGpibMsg.cpp) and every tick.
    testercomm::HsArtTesterType().store(fSCKART ? fSCKART->iTesterType : -1);
    testercomm::HsUseGPIBFormat().store(IniConfig.iI25UseGPIBFormat);
}

void ReadSetupIni(const AnsiString& setupIni, int* baud, int* bs, int* sb, int* pa)
{
    *baud = kSetupDefBaud;
    *bs = kSetupDefByteSize;
    *sb = kSetupDefStopBits;
    *pa = kSetupDefParity;
    if (!FileExists(setupIni))
        return;
    *baud = ReadIniData(setupIni, "COMPort", "BaudRate", kSetupDefBaud);
    *bs = ReadIniData(setupIni, "COMPort", "ByteSize", kSetupDefByteSize);
    *sb = ReadIniData(setupIni, "COMPort", "StopBits", kSetupDefStopBits);
    *pa = ReadIniData(setupIni, "COMPort", "Parity", kSetupDefParity);
}

int SetupIniPack()
{
    int baud, bs, sb, pa;
    ReadSetupIni(W906_GPIBAUX_SETUP_INI, &baud, &bs, &sb, &pa);
    return testercomm::HsPackAuxFraming(baud, bs, sb, pa);
}

int Prepare()
{
    g_applies = false;
    g_startPack = -1;
    if (TestIF.iTestType != GPIB_MODE || !W906_GpibAuxPortOn(W906_GPIBAUX_GENERAL_INI, CUSTOMER_CODE))
        return -1;
    g_applies = true;

    const AnsiString recipe = GetLastOpenFN();
    const AnsiString td = DataPath + recipe + "\\Tester.Data";
    RS232_DATA rd = TestIF_File.Rs232_Data;
    AnsiString detail;
    const int r = W906_GpibAuxSeedRecipeFile(td, W906_GPIBAUX_SETUP_INI, &rd, &detail);
    if (r == 1)
    {
        // what golden spbSaveClick does after SaveSetupFile: the in-memory copy (ReadTestIFFile), the page, the recipe
        // backup.  SECS SaveRecipe is not reported: no operator saved (see the ledger, P6 Q2).
        TestIF_File.Rs232_Data = rd;
        if (W906_GpibAuxRefreshTesterIfPage)
            W906_GpibAuxRefreshTesterIfPage();   // else a later TesterIF page save would write the old widget values back
        if (fMain)
            fMain->BackupSetupFile();                                           //Ifor 20170620 (wei) add Auto BackUp Setup File & Last Data
        NewRecordProcess("", "TesterIF", "P6 Q2(a): recipe " + recipe + " [RS-232C] seeded from " +
                                             AnsiString(W906_GPIBAUX_SETUP_INI) + " [COMPort] (GPIB extra RS232 port): " +
                                             detail);
    }
    else if (r < 0)
    {
        NewRecordProcess("", "TesterIF", "P6 Q2(a): recipe " + recipe + " not seeded (" + td +
                                             " missing or not writable) -- the GPIB extra RS232 port keeps " +
                                             AnsiString(W906_GPIBAUX_SETUP_INI));
    }
    g_startPack = W906_GpibAuxPackRecipe(TestIF_File.Rs232_Data);
    if (r < 0)
        return -1;
    if (g_startPack < 0)
    {
        AnsiString s;
        s.sprintf("P6 2A: recipe %s [RS-232C] BaudRate=%d Bit Length=%d Stop Bit=%d Parity=%d is not a usable framing -- "
                  "the GPIB extra RS232 port keeps %s", recipe.c_str(), TestIF_File.Rs232_Data.Baud_Rate,
                  TestIF_File.Rs232_Data.Bit_Length, TestIF_File.Rs232_Data.Stop_Bit, TestIF_File.Rs232_Data.Parity,
                  W906_GPIBAUX_SETUP_INI);
        NewRecordProcess("", "TesterIF", s);
    }
    return g_startPack;
}

void W906_GpibAuxEnable(bool on)
{
    g_enabled = on;
    g_applies = g_deferred = g_asked = false;
    g_startPack = -1;
    testercomm::HsGpibAuxFraming().store(-1);
}

bool W906_GpibAuxPortOn(const AnsiString& gpibGeneralIni, int customerCode)
{
    // golden (V906 GpibAux.cpp OpenTesterComm)                                //Jou 20240828 : 改成可以開關RS232功能
    const bool bDefault = customerCode == CC_HONPREC_QC || customerCode == CC_MAXIM_THAILAND ||
                          customerCode == CC_MAXIM || customerCode == CC_Microchip_Thai ||
                          customerCode == CC_Microchip_Phil || customerCode == CC_Microchip_China ||
                          customerCode == CC_SCC;
    if (!FileExists(gpibGeneralIni))
        return bDefault;
    return ReadIniData(gpibGeneralIni, "OpenTesterComm", "RS232", bDefault);
}

int W906_GpibAuxPackRecipe(const RS232_DATA& rd)
{
    // Out-of-range indices fall into golden CheckRs232StandardIni's else branch, as the mapping functions document.
    return testercomm::HsPackAuxFraming(rd.Baud_Rate, W906_Rs232ByteSizeCode(rd.Bit_Length),
                                        W906_Rs232StopBitsCode(rd.Stop_Bit), W906_Rs232ParityCode(rd.Parity));
}

int W906_GpibAuxSeedRecipeFile(const AnsiString& testerData, const AnsiString& setupIni, RS232_DATA* rd,
                               AnsiString* detail)
{
    if (!FileExists(testerData))
        return -1;
    if (ReadIniData(testerData, "RS-232C", W906_GPIBAUX_MARKER, 0) == 1)
        return 0;

    int baud, bs, sb, pa;
    ReadSetupIni(setupIni, &baud, &bs, &sb, &pa);
    RS232_DATA nd = *rd;
    if (baud > 0)
        nd.Baud_Rate = baud;
    const int bl = W906_Rs232BitLengthFromCode(bs), sbi = W906_Rs232StopBitFromCode(sb), pai = W906_Rs232ParityFromCode(pa);
    if (bl >= 0)
        nd.Bit_Length = bl;
    if (sbi >= 0)
        nd.Stop_Bit = sbi;
    if (pai >= 0)
        nd.Parity = pai;

    // the keys and value forms golden SaveSetupFile writes (cTesterIF.cpp; V906 TestIF_File_TesterIF.gen.inc :932-935)
    WriteIniData(testerData, "RS-232C", "BaudRate", nd.Baud_Rate);
    WriteIniData(testerData, "RS-232C", "Bit Length", nd.Bit_Length);
    WriteIniData(testerData, "RS-232C", "Stop Bit", nd.Stop_Bit);
    WriteIniData(testerData, "RS-232C", "Parity", nd.Parity);
    WriteIniData(testerData, "RS-232C", W906_GPIBAUX_MARKER, 1);
    if (ReadIniData(testerData, "RS-232C", W906_GPIBAUX_MARKER, 0) != 1 ||
        ReadIniData(testerData, "RS-232C", "BaudRate", -1) != nd.Baud_Rate)
        return -1;

    if (detail)
    {
        detail->sprintf("BaudRate %d->%d, Bit Length %d->%d, Stop Bit %d->%d, Parity %d->%d (Setup.ini%s ByteSize=%d "
                        "StopBits=%d Parity=%d)", rd->Baud_Rate, nd.Baud_Rate, rd->Bit_Length, nd.Bit_Length,
                        rd->Stop_Bit, nd.Stop_Bit, rd->Parity, nd.Parity,
                        FileExists(setupIni) ? "" : " missing, engine defaults", bs, sb, pa);
    }
    *rd = nd;
    return 1;
}

void W906_GpibAuxBeforeBridgeStart(int effectiveTestType)
{
    g_applies = g_deferred = g_asked = false;
    g_startPack = -1;
    int publish = -1;
    if (g_enabled && effectiveTestType == GPIB_MODE && TestIF.iTestType == GPIB_MODE)
    {
        if (InitialOK)
            publish = Prepare();
        else
            g_deferred = true;   // the recipe may not be loaded yet: W906_GpibAuxNeedsRestart decides later
    }
    testercomm::HsGpibAuxFraming().store(publish);
}

bool W906_GpibAuxNeedsRestart(bool bridgeUp)
{
    if (!g_enabled || !bridgeUp || g_asked || !InitialOK || SystemStart)
        return false;
    if (g_deferred)
    {
        // The engine took Setup.ini; restart only when the recipe says otherwise.
        g_deferred = false;
        const int publish = Prepare();
        testercomm::HsGpibAuxFraming().store(publish);
        if (publish < 0 || publish == SetupIniPack())
            return false;
        g_asked = true;
        return true;
    }
    if (!g_applies || W906_GpibAuxPackRecipe(TestIF_File.Rs232_Data) == g_startPack)
        return false;
    g_asked = true;
    return true;
}

int TesterCommHub::EngineSideHandler(const std::string& payload, void* ctx)
{
    TesterCommHub* hub = static_cast<TesterCommHub*>(ctx);
    TesterEngine* e = hub->engine_;
    if (e == 0)
        return -1;
    try
    {
        return e->OnHandlerMessage(payload);
    }
    catch (...)
    {
        hub->handlerErrors_.fetch_add(1);   // the sender still gets an answer instead of waiting for the timeout
        return -1;
    }
}

void TesterCommHub::StopEngine()
{
    mailbox_.SetHandler(kEngineSide, 0, 0);   // new Handler sends now get kNoReceiver
    thread_.Stop();                            // loop answers what was already queued, then engine->Stop()
    mailbox_.Reset();
    delete engine_;
    engine_ = 0;
}

bool TesterCommHub::SelectTestType(int testType)
{
    if (testType == type_)
        return engine_ != 0 && thread_.Running();   // unchanged: golden does not relaunch the bridge

    StopEngine();
    type_ = testType;
    if (testType < 0 || testType >= kTestTypeCount || factories_[testType] == 0)
        return false;

    engine_ = factories_[testType]();
    if (engine_ == 0)
        return false;
    mailbox_.SetHandler(kEngineSide, &TesterCommHub::EngineSideHandler, this);
    if (!thread_.Start(engine_, &mailbox_))
    {
        StopEngine();
        return false;
    }
    return true;
}

bool TesterCommHub::Restart()
{
    const int t = type_;
    if (t < 0)
        return false;
    StopEngine();
    type_ = -1;
    return SelectTestType(t);
}

bool TesterCommHub::IsUp() const
{
    return engine_ != 0 && thread_.Running() && engine_->IsUp();
}

void TesterCommHub::Shutdown()
{
    StopEngine();
    type_ = -1;
}

bool TesterCommThread::Start(TesterEngine* engine, SyncMailbox* mailbox)
{
    if (thread_.joinable() || engine == 0 || mailbox == 0)
        return false;
    engine_ = engine;
    mailbox_ = mailbox;
    stop_.store(false);
    startFailed_.store(false);
    running_.store(true);
    if (!thread_.start(&TesterCommThread::Entry, this))
    {
        running_.store(false);
        return false;
    }
    return true;
}

void TesterCommThread::Stop()
{
    if (!thread_.joinable())
        return;
    stop_.store(true);
    if (mailbox_ != 0)
        ::SetEvent(mailbox_->WakeHandle(kEngineSide));
    thread_.join();
    running_.store(false);
}

void TesterCommThread::Entry(void* self)
{
    static_cast<TesterCommThread*>(self)->Loop();
}

void TesterCommThread::Loop()
{
    bool started = false;
    try
    {
        started = engine_->Start(mailbox_);
    }
    catch (...)
    {
        errors_.fetch_add(1);
    }
    if (!started)
    {
        startFailed_.store(true);
        running_.store(false);
        return;
    }

    while (!stop_.load())
    {
        heartbeat_.fetch_add(1);
        unsigned waitMs = 10;
        try
        {
            mailbox_->Poll(kEngineSide);
            waitMs = engine_->RunOnce();
        }
        catch (...)
        {
            errors_.fetch_add(1);
            waitMs = 10;
        }
        if (stop_.load())
            break;
        ::WaitForSingleObject(mailbox_->WakeHandle(kEngineSide), waitMs);
    }

    try
    {
        mailbox_->Poll(kEngineSide);   // answer anything already queued so no Handler sender waits for a timeout
        engine_->Stop();
    }
    catch (...)
    {
        errors_.fetch_add(1);
    }
    running_.store(false);
}

// ===========================================================================
//  TesterComm/TesterCommThread.h -- the single TesterComm thread (user ruling 20260926: GPIB／RS232／TCPIP share
//  one thread; it must be separate from the machine thread and must not interfere with it).
//  AI(W906-GB-P0) 20260926.
//
//  Loop (golden references: H9046_32GPIB Unit2.cpp TMyThread::Execute -- SleepEx(1) + ProcessAddress/ProcessMessage;
//  RS232Standard Timer1 300 ms):
//      engine->Start(mailbox)
//      while (!stop) { heartbeat++; mailbox->Poll(engine side); ms = engine->RunOnce(); wait(mailbox wake, ms) }
//      engine->Stop()
//  Exceptions thrown by the engine are caught and counted so a faulty engine cannot take the process down;
//  the thread keeps running (the machine thread is never affected either way).
// ===========================================================================
#ifndef TESTERCOMM_TESTERCOMMTHREAD_H
#define TESTERCOMM_TESTERCOMMTHREAD_H

#include "TesterComm/TesterEngine.h"

#include <atomic>

namespace testercomm {

class TesterCommThread
{
public:
    TesterCommThread();
    ~TesterCommThread();

    // Starts the thread running `engine` (not owned).  Returns false if already running or the OS refused.
    bool Start(TesterEngine* engine, SyncMailbox* mailbox);

    // Signals the loop to finish, waits for engine->Stop() and joins.  Safe to call when not running.
    void Stop();

    bool Running() const { return running_.load(); }
    bool StartFailed() const { return startFailed_.load(); }
    unsigned long Heartbeat() const { return heartbeat_.load(); }   // loop iterations (watchdog breadcrumb)
    unsigned long EngineErrors() const { return errors_.load(); }   // exceptions caught from the engine

private:
    TesterCommThread(const TesterCommThread&);
    TesterCommThread& operator=(const TesterCommThread&);

    static void Entry(void* self);
    void Loop();

    webbridge::WbThread thread_;
    TesterEngine* engine_;
    SyncMailbox* mailbox_;
    std::atomic<bool> stop_;
    std::atomic<bool> running_;
    std::atomic<bool> startFailed_;
    std::atomic<unsigned long> heartbeat_;
    std::atomic<unsigned long> errors_;
};

}  // namespace testercomm

#endif

// ===========================================================================
//  TesterComm/HandlerSettings.h -- Handler -> engine settings snapshot (tester-comm P6).
//  AI(W906-GB-P6) 20260926.  暫照建議，待使用者確認 (decision #5) where noted.
//
//  The golden bridges were separate programs that read some settings from their own ini files.  Rulings C-2 say a few
//  of them follow the HANDLER's value instead.  No MessageDef packet field carries them (the MV / VM layout is kept
//  identical to the BCB programs), so the Handler thread publishes them here and the TesterComm thread reads them.
//  One writer (Handler thread), one reader (TesterComm thread); plain atomics, -1 = "not published" (e.g. an engine
//  run without the Handler side, as in ctest) -> the engine keeps golden behaviour.
//  Function-local statics instead of C++17 inline variables: MinGW 6.3 has no inline variables.
// ===========================================================================
#ifndef HT9045_TESTERCOMM_HANDLERSETTINGS_H
#define HT9045_TESTERCOMM_HANDLERSETTINGS_H

#include <atomic>

namespace testercomm {

// Ruling 3A, decision #5 Q1 暫照建議 (a): the Auto Retest tester brand the Handler holds now (fSCKART->iTesterType,
// 0 = Flex, 1 = 93K).  The Handler keeps golden's own learning (LOTSTATUS -> 0, SRQMASK -> 1).
inline std::atomic<int>& HsArtTesterType() { static std::atomic<int> v(-1); return v; }

// Ruling 4A (decision #5 Q4 暫照建議 A): the Handler-ID reply format, IniConfig.iI25UseGPIBFormat (config.ini).
inline std::atomic<int>& HsUseGPIBFormat() { static std::atomic<int> v(-1); return v; }

// Ruling 2A + user ruling Q2 = (a) (20260926): the framing of the GPIB program's extra RS232 port (golden RS232.cpp
// TfRS232Main::CommTester) follows the recipe (TestIF_File.Rs232_Data) instead of D:\RS232Standard\System\Setup.ini
// [COMPort].  Published by the Handler before each bridge start (TesterComm/Handler/HandlerGpibAux.cpp), read by the
// engine once, in LoadSetupData (golden FormShow).  One atomic so the engine can never see half of an update:
//   bits 0-2 Parity (SPComm 0:None 1:Odd 2:Even 3:Mark 4:Space), bits 3-4 StopBits (0:_1 1:_1_5 2:_2),
//   bits 5-6 ByteSize (0:_5 1:_6 2:_7 3:_8), bits 8.. BaudRate.   -1 = not published -> golden Setup.ini values.
inline std::atomic<int>& HsGpibAuxFraming() { static std::atomic<int> v(-1); return v; }

inline int HsPackAuxFraming(int baud, int byteSize, int stopBits, int parity)
{
    if (baud <= 0 || baud > 0x7fffff || byteSize < 0 || byteSize > 3 || stopBits < 0 || stopBits > 2 ||
        parity < 0 || parity > 4)
        return -1;
    return (baud << 8) | (byteSize << 5) | (stopBits << 3) | parity;
}

inline bool HsUnpackAuxFraming(int v, int* baud, int* byteSize, int* stopBits, int* parity)
{
    if (v < 0)
        return false;
    *baud = v >> 8;
    *byteSize = (v >> 5) & 3;
    *stopBits = (v >> 3) & 3;
    *parity = v & 7;
    return true;
}

}  // namespace testercomm

#endif

// ===========================================================================
//  TesterComm/Handler/HandlerGpibAux.h -- the GPIB program's extra RS232 port follows the recipe (tester-comm P6).
//  AI(W906-GB-P6) 20260926.  User ruling 2A + Q2 = (a) (github-59 relayed, steven-handoff FROM_STEVEN §1 P6).
//
//  Golden: H9046_32GPIB.exe opens a second COM port (RS232.cpp TfRS232Main::CommTester) for customer codes 0 / 860-863 /
//  943 / 985 or when its general.ini [OpenTesterComm] RS232=1, with the framing from D:\RS232Standard\System\Setup.ini
//  [COMPort].  The Handler writes that file only for RS232-mode recipes (cTesterIF.cpp CheckRs232StandardIni), so a
//  GPIB-mode recipe's [RS-232C] values were never used and are often defaults.
//  Ruling 2A: the port follows the Handler recipe (TestIF_File.Rs232_Data).  Ruling Q2 (a): on the first run, each
//  GPIB-mode recipe is seeded ONCE from the current Setup.ini [COMPort] values (marker [RS-232C] W906_SeededFromSetupIni=1
//  in its Tester.Data); from then on the recipe is authoritative.
//
//  Only a GPIB-mode recipe (TestIF.iTestType==GPIB_MODE, bridge on the GPIB engine) with the extra port on is affected.
//  Every other case publishes -1 and the engine keeps golden's Setup.ini values.  Nothing runs until
//  W906_GpibAuxEnable(true) (TesterCommWiring.cpp W906_TesterCommInit, i.e. wb_serve): a ctest that drives
//  THandlerTesterSide directly never reads or writes the production recipe / Setup.ini files.
// ===========================================================================
#ifndef HT9045_TESTERCOMM_HANDLER_HANDLERGPIBAUX_H
#define HT9045_TESTERCOMM_HANDLER_HANDLERGPIBAUX_H

#include "vclcompat/vcl_compat.h"   // AnsiString
#include "cprod.h"                // RS232_DATA

// golden paths (golden GPIB RS232.cpp OpenTesterComm / LoadSetupData)
#define W906_GPIBAUX_GENERAL_INI  "D:\\GPIB9045\\system\\general.ini"
#define W906_GPIBAUX_SETUP_INI    "D:\\RS232Standard\\System\\Setup.ini"
#define W906_GPIBAUX_MARKER       "W906_SeededFromSetupIni"   // Tester.Data [RS-232C]

// Composition root switch (TesterCommWiring.cpp).  Off = everything below is inert and -1 is published.
void W906_GpibAuxEnable(bool on);

// Installed by FileRW/TestIF_File_TesterIF.cpp (wb_serve only): refreshes the TesterIF page's widgets after seeding.
extern void (*W906_GpibAuxRefreshTesterIfPage)();

// golden GPIB RS232.cpp OpenTesterComm (V906 TesterComm/Gpib/GpibAux.cpp): is the extra port opened?  Read-only here
// (the engine's CheckAndReadIniData writes the default back; the Handler does not).
bool W906_GpibAuxPortOn(const AnsiString& gpibGeneralIni, int customerCode);

// The recipe's framing as the engine's packed value (TesterComm/HandlerSettings.h), -1 when a field is invalid.
int W906_GpibAuxPackRecipe(const RS232_DATA& rd);

// Seed one recipe file from Setup.ini [COMPort] -- file work only (no fMain, no page, no log), for the ctest.
//   1 = seeded now (rd updated to the written values, *detail says old -> new), 0 = marker already there (nothing
//   written), -1 = no recipe file or the write did not stick.  A missing Setup.ini seeds the engine's own defaults
//   (9600 / 7 / 1 / Even, GpibAux.cpp LoadSetupData) -- what the port used; a value that is not an SPComm ordinal keeps
//   the recipe's value for that field.
int W906_GpibAuxSeedRecipeFile(const AnsiString& testerData, const AnsiString& setupIni, RS232_DATA* rd,
                               AnsiString* detail);

// Handler thread, THandlerTesterSide::StartBridgeProgram right before the engine (re)starts.  Seeds the current recipe
// if needed (normal save tail: fMain->BackupSetupFile(), page widgets refreshed, NewRecordProcess) and publishes
// HsGpibAuxFraming for the engine's LoadSetupData.
void W906_GpibAuxBeforeBridgeStart(int effectiveTestType);

// Handler thread, every tick (TesterCommWiring.cpp): true = the port no longer matches the recipe (the recipe's RS232
// values changed, or the first start ran before the recipe was loaded) -> the caller closes the bridge, which then
// restarts through WakeupGPIB like golden's CheckRs232StandardIni -> CloseGpibProgram.  Only asks once per start.
bool W906_GpibAuxNeedsRestart(bool bridgeUp);

#endif
